            write_length_r_count = write_length_r_count + 1;
            if (write_length_r_count == length_r_OPERATE_DEPTH) begin
                write_length_r_run_flag <= 0; 
                length_r_write_data_finish <= 1;
            end
        end
    end
end

initial begin : write_length_r
    integer write_length_r_resp;
    integer process_num ;
    integer get_ack;
    integer four_byte_num;
    integer c_bitwidth;
    integer i;
    integer j;
    reg [31 : 0] length_r_data_tmp_reg;
    wait(reset === 1);
    @(posedge clk);
    c_bitwidth = length_r_c_bitwidth;
    process_num = 3;
    count_c_data_four_byte_num_by_bitwidth (c_bitwidth , four_byte_num) ;
    while (1) begin
        process_3_finish <= 0;

        if (ongoing_process_number === process_num && process_busy === 0 ) begin
            get_ack = 1;
            if (write_length_r_run_flag === 1 && get_ack === 1) begin
                process_busy = 1;
                //write length_r data 
                for (i = 0 ; i < four_byte_num ; i = i+1) begin
                    if (length_r_c_bitwidth < 32) begin
                        length_r_data_tmp_reg = mem_length_r[write_length_r_count];
                    end
                    else begin
                        for (j=0 ; j<32 ; j = j + 1) begin
                            if (i*32 + j < length_r_c_bitwidth) begin
                                length_r_data_tmp_reg[j] = mem_length_r[write_length_r_count][i*32 + j];
                            end
                            else begin
                                length_r_data_tmp_reg[j] = 0;
                            end
                        end
                    end
                    write (length_r_data_in_addr + write_length_r_count * four_byte_num * 4 + i * 4, length_r_data_tmp_reg, write_length_r_resp);
                end
                process_busy = 0;
                write_one_length_r_data_done <= 1;
                @(posedge clk);
                write_one_length_r_data_done <= 0;
            end   
            process_3_finish <= 1;
        end
        @(posedge clk);
    end    
end
always @(reset or posedge clk) begin
    if (reset == 0) begin
        start_write_data_finish <= 0;
        write_start_run_flag <= 0; 
        write_start_count = 0;
        count_operate_depth_by_bitwidth_and_depth (start_c_bitwidth, start_DEPTH, start_OPERATE_DEPTH);
    end
    else begin
        if (TRAN_CONFIGBUS_start_in === 1) begin
            start_write_data_finish <= 0;
        end
        if (AESL_ready_reg === 1) begin
            write_start_run_flag <= 1; 
            write_start_count = 0;
        end
        if (write_one_start_data_done === 1) begin
            write_start_count = write_start_count + 1;
            if (write_start_count == start_OPERATE_DEPTH) begin
                write_start_run_flag <= 0; 
                start_write_data_finish <= 1;
            end
        end
    end
end

initial begin : write_start
    integer write_start_resp;
    integer process_num ;
    integer get_ack;
    integer four_byte_num;
    integer c_bitwidth;
    integer i;
    integer j;
    reg [31 : 0] start_data_tmp_reg;
    wait(reset === 1);
    @(posedge clk);
    c_bitwidth = start_c_bitwidth;
    process_num = 4;
    count_c_data_four_byte_num_by_bitwidth (c_bitwidth , four_byte_num) ;
    while (1) begin
        process_4_finish <= 0;

        if (ongoing_process_number === process_num && process_busy === 0 ) begin
            get_ack = 1;
            if (write_start_run_flag === 1 && get_ack === 1) begin
                process_busy = 1;
                //write start data 
                for (i = 0 ; i < four_byte_num ; i = i+1) begin
                    if (start_c_bitwidth < 32) begin
                        start_data_tmp_reg = mem_start[write_start_count];
                    end
                    else begin
                        for (j=0 ; j<32 ; j = j + 1) begin
                            if (i*32 + j < start_c_bitwidth) begin
                                start_data_tmp_reg[j] = mem_start[write_start_count][i*32 + j];
                            end
                            else begin
                                start_data_tmp_reg[j] = 0;
                            end
                        end
                    end
                    write (start_data_in_addr + write_start_count * four_byte_num * 4 + i * 4, start_data_tmp_reg, write_start_resp);
                end
                process_busy = 0;
                write_one_start_data_done <= 1;
                @(posedge clk);
                write_one_start_data_done <= 0;
            end   
            process_4_finish <= 1;
        end
        @(posedge clk);
    end    
end

always @(reset or posedge clk) begin
    if (reset == 0) begin
        write_start_run_flag <= 0; 
        write_start_count <= 0;
    end
    else begin
        if (write_start_count >= 10) begin
            write_start_run_flag <= 0; 
        end
        else if (TRAN_CONFIGBUS_write_start_in === 1) begin
            write_start_run_flag <= 1; 
        end
        if (AESL_write_start_finish === 1) begin
            write_start_count <= write_start_count + 1;
            write_start_run_flag <= 0; 
        end
    end
end

initial begin : write_start
    reg [DATA_WIDTH - 1 : 0] write_start_tmp;
    integer process_num;
    integer write_start_resp;
    wait(reset === 1);
    @(posedge clk);
    process_num = 5;
    while (1) begin
        process_5_finish = 0;
        if (ongoing_process_number === process_num && process_busy === 0 ) begin
            if (write_start_run_flag === 1) begin
                process_busy = 1;
                write_start_tmp=0;
                write_start_tmp[0 : 0] = 1;
                write (START_ADDR, write_start_tmp, write_start_resp);
                process_busy = 0;
                AESL_write_start_finish <= 1;
                @(posedge clk);
                AESL_write_start_finish <= 0;
            end
            process_5_finish <= 1;
        end 
        @(posedge clk);
    end
end

//------------------------Task and function-------------- 
task read_token; 
    input integer fp; 
    output reg [127 : 0] token;
    integer ret;
    begin
        token = "";
        ret = 0;
        ret = $fscanf(fp,"%s",token);
    end 
endtask 
 
//------------------------Read file------------------------ 
 
// Read data from file 
initial begin : read_length_r_file_process 
  integer fp; 
  integer ret; 
  integer factor; 
  reg [127 : 0] token; 
  reg [127 : 0] token_tmp; 
  //reg [length_r_c_bitwidth - 1 : 0] token_tmp; 
  reg [DATA_WIDTH - 1 : 0] mem_tmp; 
  reg [ 8*5 : 1] str;
  integer transaction_idx; 
  integer i; 
  transaction_idx = 0; 
  mem_tmp [DATA_WIDTH - 1 : 0] = 0;
  count_seperate_factor_by_bitwidth (length_r_c_bitwidth , factor);
  fp = $fopen(`TV_IN_length_r ,"r"); 
  if(fp == 0) begin                               // Failed to open file 
      $display("Failed to open file \"%s\"!", `TV_IN_length_r); 
      $finish; 
  end 
  read_token(fp, token); 
  if (token != "[[[runtime]]]") begin             // Illegal format 
      $display("ERROR: Simulation using HLS TB failed.");
      $finish; 
  end 
  read_token(fp, token); 
  while (token != "[[[/runtime]]]") begin 
      if (token != "[[transaction]]") begin 
          $display("ERROR: Simulation using HLS TB failed.");
          $finish; 
      end 
      read_token(fp, token);                        // skip transaction number 
      @(posedge clk);
      # 0.2;
      while(AESL_ready_reg !== 1) begin
          @(posedge clk); 
          # 0.2;
      end
      for(i = 0; i < length_r_DEPTH; i = i + 1) begin 
          read_token(fp, token); 
          ret = $sscanf(token, "0x%x", token_tmp); 
          if (factor == 4) begin
              if (i%factor == 0) begin
                  mem_tmp [7 : 0] = token_tmp;
              end
              if (i%factor == 1) begin
                  mem_tmp [15 : 8] = token_tmp;
              end
              if (i%factor == 2) begin
                  mem_tmp [23 : 16] = token_tmp;
              end
              if (i%factor == 3) begin
                  mem_tmp [31 : 24] = token_tmp;
                  mem_length_r [i/factor] = mem_tmp;
                  mem_tmp [DATA_WIDTH - 1 : 0] = 0;
              end
          end
          if (factor == 2) begin
              if (i%factor == 0) begin
                  mem_tmp [15 : 0] = token_tmp;
              end
              if (i%factor == 1) begin
                  mem_tmp [31 : 16] = token_tmp;
                  mem_length_r [i/factor] = mem_tmp;
                  mem_tmp [DATA_WIDTH - 1: 0] = 0;
              end
          end
          if (factor == 1) begin
              mem_length_r [i] = token_tmp;
          end
      end 
      if (factor == 4) begin
          if (i%factor != 0) begin
              mem_length_r [i/factor] = mem_tmp;
          end
      end
      if (factor == 2) begin
          if (i%factor != 0) begin
              mem_length_r [i/factor] = mem_tmp;
          end
      end 
      read_token(fp, token); 
      if(token != "[[/transaction]]") begin 
          $display("ERROR: Simulation using HLS TB failed.");
          $finish; 
      end 
      read_token(fp, token); 
      transaction_idx = transaction_idx + 1; 
  end 
  $fclose(fp); 
end 
 
